def check_authorization(token_string, subject_id, data_source, timestamp):
    if not token_string:
        return False

    user_record = data_source.get(subject_id)
    if not user_record or not isinstance(user_record, dict):
        return False

    token_is_correct = (token_string == user_record.get('value'))

    expiry = user_record.get('expiry')
    token_is_current = isinstance(expiry, (int, float)) and (timestamp < expiry)

    if token_is_correct and token_is_current:
        return True

    return False
